use alloc::{vec,vec::Vec,string::String};
use crate::{ps_scan_abi::{PsMappedImageViewV1,PsMappedSegment,PsMappedExtent},mapped_property_api::{ps_resolve_mapped_property_v1,PsMappedPropertyResult}};
const DEV:&[&str]=&["Debug.OOMMemReport","GameplayTags.PackingTest","GameplayTags.PrintReport","Reattach.MaterialInstances","Reattach.Materials","TaskGraph.Randomize","TimedMemReport.Delay","gc.StressTestGC","net.TestObjRefSerialize","p.DebugTimeDiscrepancy"];
const TEST:&[&str]=&["AudioComponent Dump","CLEANSCREENSHOTS","CONTENTCOMPARISON","CompressionState","ConsoleHelp.html","DUMPMATERIALSTATS","DUMPPARTICLECOUNTS","DebugTrackedTextures","Dry audio isolated","Dump Shadow Setup:"];
const SHIP:&[&str]=&["Plugin commandlet disabled in shipping mode.","Logging interval in shipping. If set, this overrides archive.FlushInterval","log.flushInterval.Shipping","Engine.VerifyLoadMapWorldCleanup.Severity.Shipping","Engine.VerifyLoadMapWorldCleanup.TraceMode.Shipping","GameFeaturePlugin.LeakedAssetTrace.Severity.Shipping","GameFeaturePlugin.LeakedAssetTrace.TraceMode.Shipping","LevelStreaming.Profiling.Enabled.Shipping","PluginManager.LeakedAssetTrace.Severity.Shipping","PluginManager.LeakedAssetTrace.TraceMode.Shipping"];
const ON:&[&str]=&["Cycle counters (flat)","Cycle counters (hierarchy)","Dumps RHI memory stats to the log","Empty stat command!","FSimpleDelegateGraphTask.StatCmd","FSimpleDelegateGraphTask.StatsToGame","Frame Messages Condensed","Here is the brief list of stats console commands","If true, dump stat packets.","Particle Dynamic Memory Stats","ParticleData,Total(Bytes),FMath::Max(Bytes)","RHI resource memory (not tracked by our allocator)"];
fn bytes(strings:&[&str])->Vec<u8>{let mut b=vec![0xc3,0,0,0];for s in strings{b.extend(s.encode_utf16().flat_map(u16::to_le_bytes));b.extend([0,0]);}b}
fn view(b:&[u8],s:&PsMappedSegment)->PsMappedImageViewV1{PsMappedImageViewV1{abi_version:1,format:1,segments:s,segment_count:1,text_base:b.as_ptr() as usize as u64,image_base:0,eh_frame:PsMappedExtent{address:0,size:0},eh_frame_hdr:PsMappedExtent{address:0,size:0},pe_exception_directory:PsMappedExtent{address:0,size:0}}}
fn fixture(strings:&[&str],id:u32)->(i32,u32){let b=bytes(strings);let s=PsMappedSegment{bytes:b.as_ptr(),size:b.len(),runtime_address:b.as_ptr() as usize as u64,permissions:5,reserved:0};let mut out=PsMappedPropertyResult{value:999,reserved:999};let v=view(&b,&s);let status=unsafe{ps_resolve_mapped_property_v1(&v,id,&mut out)};assert_eq!(out.reserved,0);if status!=0{assert_eq!(out.value,0);}(status,out.value)}
#[test]fn three_config_wire_values_and_independent_stats_off_on(){for (markers,want) in [(DEV,2),(TEST,3),(SHIP,1)]{assert_eq!(fixture(markers,1),(0,want));assert_eq!(fixture(markers,2),(0,1));let on=markers.iter().chain(ON).copied().collect::<Vec<_>>();assert_eq!(fixture(&on,1),(0,want));assert_eq!(fixture(&on,2),(0,2));}}
#[test]fn marker_minimum_unknown_and_axis_margin(){assert_eq!(fixture(&[],1),(3,0));assert_eq!(fixture(&DEV[..9],1),(3,0));assert_eq!(fixture(&DEV[..9],2),(3,0));let uncertain=DEV.iter().chain(ON[..2].iter()).copied().collect::<Vec<_>>();assert_eq!(fixture(&uncertain,1),(0,2));assert_eq!(fixture(&uncertain,2),(3,0));let enough=DEV.iter().chain(ON[..3].iter()).copied().collect::<Vec<_>>();assert_eq!(fixture(&enough,2),(0,2));}
#[test]fn no_configuration_name_shortcut_and_case_exactness(){assert_eq!(fixture(&["Shipping","Development","Test","Off","On"],1),(3,0));let lower=DEV.iter().map(|s|s.to_ascii_lowercase()).collect::<Vec<String>>();let lower=lower.iter().map(String::as_str).collect::<Vec<_>>();assert_eq!(fixture(&lower,1),(3,0));}
#[test]fn property_c_abi_refusals_clear_unknown(){let b=bytes(DEV);let s=PsMappedSegment{bytes:b.as_ptr(),size:b.len(),runtime_address:b.as_ptr() as usize as u64,permissions:5,reserved:0};let mut v=view(&b,&s);let mut out=PsMappedPropertyResult{value:999,reserved:999};assert_eq!(unsafe{ps_resolve_mapped_property_v1(&v,0,&mut out)},1);assert_eq!(out.value,0);out.value=999;v.abi_version=2;assert_eq!(unsafe{ps_resolve_mapped_property_v1(&v,1,&mut out)},2);assert_eq!(out.value,0);assert_eq!(unsafe{ps_resolve_mapped_property_v1(core::ptr::null(),1,&mut out)},1);assert_eq!(unsafe{ps_resolve_mapped_property_v1(&v,1,core::ptr::null_mut())},1);}
